<template><el-container class="chat"><el-header><el-button @click="router.push('/health-home')">返回首页</el-button><h3>在线健康咨询</h3><el-tag>{{online?'已连接实时通知':'正在连接通知'}}</el-tag></el-header><el-main><el-button v-if="!doctor" type="primary" @click="request">申请问询</el-button><el-button @click="load">刷新队列</el-button><el-row :gutter="20"><el-col :span="8"><el-card v-for="c in queue" :key="c.id" @click="select(c)"><strong>{{c.nick_name}}</strong><p>{{c.status}} · 前面 {{c.ahead}} 位</p><p>{{c.practitionerOnline?'健康师在线':'健康师暂未上线，请等待'}}</p><el-button v-if="doctor&&c.status==='WAITING'" @click.stop="accept(c)">接诊</el-button></el-card></el-col><el-col :span="16"><el-card v-if="current"><template #header>咨询 #{{current.id}} · {{current.status}} <el-button @click="close">结束咨询</el-button></template><section class="messages"><p v-for="m in messages" :key="m.id" :class="{mine:m.sender_id===userId}"><strong>{{m.sender_id===userId?'我':'对方'}}</strong> {{m.content}} <small>{{m.created_at}}</small></p></section><el-input v-model="content" type="textarea" maxlength="2000" placeholder="输入消息" :disabled="current.status!=='ACTIVE'"/><el-button type="primary" @click="send" :disabled="current.status!=='ACTIVE'">发送</el-button></el-card><el-empty v-else description="选择一条咨询记录"/></el-col></el-row></el-main></el-container></template>
<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue';import {useRouter} from 'vue-router';import {call} from '@/api/health';import useUserStore from '@/store/modules/user';import {ElMessage} from 'element-plus'
const router=useRouter(),store=useUserStore(),doctor=store.roles.includes('healthyperson'),userId=store.id,queue=ref([]),current=ref(),messages=ref([]),content=ref(''),online=ref(false);let ws,timer
async function load(){queue.value=(await call('chat/queue')).data;if(current.value){current.value=queue.value.find(x=>x.id===current.value.id)||current.value;messages.value=(await call('chat/'+current.value.id+'/messages')).data}}
async function select(c){current.value=c;await load()}
async function request(){await call('chat/request','post');await load()}
async function accept(c){await call('chat/'+c.id+'/accept','post');current.value=c;await load()}
async function close(){await call('chat/'+current.value.id+'/close','post');current.value=null;await load()}
async function send(){if(!content.value.trim())return;await call('chat/'+current.value.id+'/messages','post',{content:content.value});content.value='';await load()}
onMounted(async()=>{await load();try{const ticket=(await call('chat/ticket')).data;ws=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/dev-api/health/chat/socket?ticket=${encodeURIComponent(ticket)}`);ws.onopen=()=>online.value=true;ws.onclose=()=>online.value=false;ws.onmessage=()=>load()}catch(e){ElMessage.warning('实时通知连接失败，可手动刷新')}timer=setInterval(load,5000)})
onBeforeUnmount(()=>{clearInterval(timer);ws?.close()})
</script><style scoped>.chat{min-height:100vh;background:#f1f7f6}.el-header{display:flex;align-items:center;gap:24px;background:white}.el-main{padding:32px}.el-row{margin-top:24px}.el-card{margin-bottom:12px;cursor:pointer}.messages{min-height:250px;max-height:500px;overflow:auto}.messages p{padding:12px;background:#edf5f2;border-radius:8px}.messages .mine{background:#d5efe8}small{display:block;color:#688681}</style>
